create or replace function public.get_restaurant_ai_menu_intelligence(p_days int default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();d int:=least(greatest(coalesce(p_days,90),7),365);result jsonb;begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;with stats as(select oi.menu_item_id,max(oi.item_name) item_name,max(mi.category_id::text)::uuid category_id,sum(oi.quantity)::numeric units,sum(oi.line_total_pence)::numeric revenue_pence,count(distinct oi.order_id)::numeric orders from public.order_items oi join public.orders o on o.id=oi.order_id left join public.menu_items mi on mi.id=oi.menu_item_id where o.restaurant_id=rid and o.payment_status='paid' and o.order_status<>'rejected' and o.created_at>=now()-(d||' days')::interval and oi.menu_item_id is not null group by oi.menu_item_id),pairs as(select a.menu_item_id a_id,b.menu_item_id b_id,max(a.item_name) a_name,max(b.item_name)b_name,count(distinct a.order_id)n from public.order_items a join public.order_items b on b.order_id=a.order_id and a.menu_item_id<b.menu_item_id join public.orders o on o.id=a.order_id where o.restaurant_id=rid and o.payment_status='paid' and o.order_status<>'rejected' and o.created_at>=now()-(d||' days')::interval group by a.menu_item_id,b.menu_item_id order by n desc limit 10),cats as(select c.id,c.name,coalesce(sum(s.revenue_pence),0)revenue_pence,coalesce(sum(s.units),0)units from public.menu_categories c left join stats s on s.category_id=c.id where c.restaurant_id=rid group by c.id,c.name order by revenue_pence desc),peaks as(select extract(dow from created_at)::int day_of_week,extract(hour from created_at)::int hour_of_day,count(*)orders,coalesce(sum(total_pence),0)revenue_pence from public.orders where restaurant_id=rid and payment_status='paid' and order_status<>'rejected' and created_at>=now()-(d||' days')::interval group by 1,2 order by orders desc limit 10) select jsonb_build_object('period_days',d,'best_selling',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by units desc limit 10)x),'[]'),'worst_selling',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by units,revenue_pence limit 10)x),'[]'),'most_profitable_proxy',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by revenue_pence desc limit 10)x),'[]'),'profitability_note','Item cost data is not currently stored, so revenue contribution is used as a transparent profitability proxy rather than gross profit.','frequently_purchased_together',coalesce((select jsonb_agg(to_jsonb(p)) from pairs p),'[]'),'peak_ordering_times',coalesce((select jsonb_agg(to_jsonb(p)) from peaks p),'[]'),'category_performance',coalesce((select jsonb_agg(to_jsonb(c)) from cats c),'[]'),'bundle_opportunities',coalesce((select jsonb_agg(jsonb_build_object('title','Bundle '||a_name||' + '||b_name,'menu_item_ids',jsonb_build_array(a_id,b_id),'pair_orders',n)) from pairs),'[]')) into result;return result;end$$;
revoke all on function public.get_restaurant_ai_menu_intelligence(int) from public,anon;
grant execute on function public.get_restaurant_ai_menu_intelligence(int) to authenticated;
